//! Review regressions for `pkix-revocation-http` (fetch + cache wrappers).
//!
//! Fixtures: `tests/fixtures/review/` (copied from
//! `pkix-revocation/tests/fixtures/review/`, generated by
//! `pkix-revocation/tests/gen_review_fixtures.py`). The HTTP transport is a
//! mock `RevocationFetcher`; no network. Before the fixes every `review_*`
//! test failed; `control_*` tests pin that the fixtures are sound.
//!
//! Run: cargo test -p pkix-revocation-http --features crl,ocsp --test review_http

#![cfg(all(feature = "crl", feature = "ocsp"))]

use der::Decode as _;
use pkix_path::{DefaultVerifier, TrustAnchor};
use pkix_revocation::{Error as RevError, RevocationChecker};
use pkix_revocation_http::{
    CachedHttpCrlFetcher, CachedHttpOcspFetcher, FetchError, FetchRequest, FetchResponse,
    HttpCrlFetcher, HttpOcspFetcher, InMemoryCache, RevocationFetcher,
};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;
use x509_cert::Certificate;

/// 2026-06-01T00:00:00Z — inside the review CRL and OCSP windows.
const NOW: u64 = 1_780_272_000;
const CDP_URL: &str = "http://crl.review.test/ca.crl";

fn fx(name: &str) -> Vec<u8> {
    let p = format!(
        "{}/tests/fixtures/review/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    std::fs::read(&p).unwrap_or_else(|e| panic!("{p}: {e}"))
}
fn cert(name: &str) -> Certificate {
    Certificate::from_der(&fx(name)).unwrap()
}

/// Mock transport: serves `responses[i]` on the i-th call (last one repeats)
/// for any URL, counting calls.
struct Sequence {
    responses: Vec<Vec<u8>>,
    calls: AtomicUsize,
    urls: Mutex<Vec<String>>,
}
impl Sequence {
    fn new(responses: Vec<Vec<u8>>) -> Self {
        Self {
            responses,
            calls: AtomicUsize::new(0),
            urls: Mutex::new(Vec::new()),
        }
    }
    fn calls(&self) -> usize {
        self.calls.load(Ordering::SeqCst)
    }
}
impl RevocationFetcher for Sequence {
    fn fetch(&self, req: &FetchRequest<'_>) -> Result<FetchResponse, FetchError> {
        self.urls.lock().unwrap().push(req.url.to_owned());
        let i = self.calls.fetch_add(1, Ordering::SeqCst);
        let body = self.responses[i.min(self.responses.len() - 1)].clone();
        Ok(FetchResponse {
            bytes: body,
            content_type: None,
        })
    }
}
impl RevocationFetcher for &Sequence {
    fn fetch(&self, req: &FetchRequest<'_>) -> Result<FetchResponse, FetchError> {
        (**self).fetch(req)
    }
}

fn anchor() -> TrustAnchor {
    TrustAnchor::from_cert(cert("ca.der"))
}

// ------------------------------------------------------------------ controls

#[test]
fn control_http_crl_reports_serial2_revoked() {
    let f = Sequence::new(vec![fx("base-crl.der")]);
    let h = HttpCrlFetcher::new(&f, DefaultVerifier, NOW);
    let r = h.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der"));
    assert!(matches!(r, Err(RevError::Revoked { .. })), "control: {r:?}");
    assert_eq!(f.urls.lock().unwrap().as_slice(), [CDP_URL]);
}

#[test]
fn control_http_ocsp_reports_serial2_revoked() {
    let f = Sequence::new(vec![fx("ocsp-serial2-revoked.der")]);
    let h = HttpOcspFetcher::new(&f, DefaultVerifier, NOW);
    let r = h.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der"));
    assert!(matches!(r, Err(RevError::Revoked { .. })), "control: {r:?}");
}

#[test]
fn control_offline_crl_checker_against_anchor_reports_revoked() {
    // pkix-revocation's own CrlChecker DOES override the anchor method.
    let c = pkix_revocation::CrlChecker::new(fx("base-crl.der"), NOW, DefaultVerifier).unwrap();
    let r = c.check_revocation_against_anchor(&cert("leaf-serial2.der"), &anchor());
    assert!(matches!(r, Err(RevError::Revoked { .. })), "control: {r:?}");
}

// ------------------------------------------- anchor-issued certs never checked

/// pkix-chain calls `check_revocation_against_anchor` for the certificate
/// issued directly by the trust anchor (normally the top intermediate). All
/// six HTTP wrapper types — the two plain fetchers, the two cached
/// wrappers, and the two async ones (covered in `review_async_anchor.rs`)
/// — used to inherit the trait default `Ok(())`, so that certificate was
/// never fetched or checked and a revoked intermediate passed. Each type
/// needs its own test: the default is inherited per impl, so a dropped
/// override on any one of them silently reopens the hole.
#[test]
fn review_http_crl_fetcher_checks_anchor_issued_cert() {
    let f = Sequence::new(vec![fx("base-crl.der")]);
    let h = HttpCrlFetcher::new(&f, DefaultVerifier, NOW);
    let r = h.check_revocation_against_anchor(&cert("leaf-serial2.der"), &anchor());
    assert!(
        r.is_err(),
        "revoked anchor-issued cert reported not revoked ({} fetches made); got {r:?}",
        f.calls()
    );
}

#[test]
fn review_http_ocsp_fetcher_checks_anchor_issued_cert() {
    let f = Sequence::new(vec![fx("ocsp-serial2-revoked.der")]);
    let h = HttpOcspFetcher::new(&f, DefaultVerifier, NOW);
    let r = h.check_revocation_against_anchor(&cert("leaf-serial2.der"), &anchor());
    assert!(
        r.is_err(),
        "revoked anchor-issued cert reported not revoked ({} fetches made); got {r:?}",
        f.calls()
    );
}

#[test]
fn review_cached_http_crl_fetcher_checks_anchor_issued_cert() {
    let f = Sequence::new(vec![fx("base-crl.der")]);
    let h = CachedHttpCrlFetcher::new(
        HttpCrlFetcher::new(&f, DefaultVerifier, NOW),
        InMemoryCache::new(),
    );
    let r = h.check_revocation_against_anchor(&cert("leaf-serial2.der"), &anchor());
    assert!(r.is_err(), "got {r:?} after {} fetches", f.calls());
}

#[test]
fn review_cached_http_ocsp_fetcher_checks_anchor_issued_cert() {
    let f = Sequence::new(vec![fx("ocsp-serial2-revoked.der")]);
    let h = CachedHttpOcspFetcher::new(
        HttpOcspFetcher::new(&f, DefaultVerifier, NOW),
        InMemoryCache::new(),
    );
    let r = h.check_revocation_against_anchor(&cert("leaf-serial2.der"), &anchor());
    assert!(r.is_err(), "got {r:?} after {} fetches", f.calls());
}

/// The anchor-flow OCSP request must carry a CertID computed from the
/// anchor (same bytes as the issuer-certificate flow for the same CA).
#[test]
fn anchor_ocsp_request_matches_issuer_request() {
    use pkix_revocation_http::{build_ocsp_request, build_ocsp_request_for_anchor, OcspHashAlg};
    let leaf = cert("leaf-serial2.der");
    for alg in [OcspHashAlg::Sha1, OcspHashAlg::Sha256] {
        let by_issuer = build_ocsp_request(&leaf, &cert("ca.der"), alg).unwrap();
        let by_anchor = build_ocsp_request_for_anchor(&leaf, &anchor(), alg).unwrap();
        assert_eq!(by_issuer.body, by_anchor.body, "{alg:?}");
    }
}

/// Positive counterparts: verified verdicts ARE cached (one fetch for two
/// checks), so the poisoning fix did not disable caching.
#[test]
fn cached_crl_fetcher_still_caches_verified_crl() {
    let f = Sequence::new(vec![fx("base-crl.der")]);
    let h = CachedHttpCrlFetcher::new(
        HttpCrlFetcher::new(&f, DefaultVerifier, NOW),
        InMemoryCache::new(),
    );
    for _ in 0..2 {
        let r = h.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der"));
        assert!(matches!(r, Err(RevError::Revoked { .. })), "{r:?}");
    }
    assert_eq!(f.calls(), 1);
}

#[test]
fn cached_ocsp_fetcher_still_caches_verified_response() {
    let f = Sequence::new(vec![fx("ocsp-serial2-revoked.der")]);
    let h = CachedHttpOcspFetcher::new(
        HttpOcspFetcher::new(&f, DefaultVerifier, NOW),
        InMemoryCache::new(),
    );
    for _ in 0..2 {
        let r = h.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der"));
        assert!(matches!(r, Err(RevError::Revoked { .. })), "{r:?}");
    }
    assert_eq!(f.calls(), 1);
}

/// A cached (verified) entry whose verdict is not determinative for the
/// current check — here because the second checker's clock is before the
/// CRL's thisUpdate — must not be served; the URL is refetched.
#[test]
fn cached_crl_with_non_determinative_verdict_is_refetched() {
    use std::sync::Arc;
    let cache = Arc::new(InMemoryCache::new());
    let f = Sequence::new(vec![fx("base-crl.der")]);
    let leaf = cert("leaf-serial2.der");
    let ca = cert("ca.der");

    let warm =
        CachedHttpCrlFetcher::new(HttpCrlFetcher::new(&f, DefaultVerifier, NOW), cache.clone());
    assert!(matches!(
        warm.check_revocation(&leaf, &ca),
        Err(RevError::Revoked { .. })
    ));
    assert_eq!(f.calls(), 1);

    // 2025-12-31: before the CRL's thisUpdate (2026-01-01).
    let early = CachedHttpCrlFetcher::new(
        HttpCrlFetcher::new(&f, DefaultVerifier, 1_767_139_200),
        cache,
    );
    let r = early.check_revocation(&leaf, &ca);
    assert!(matches!(r, Err(RevError::CrlExpired)), "{r:?}");
    assert_eq!(
        f.calls(),
        2,
        "non-determinative cached verdict must trigger a refetch"
    );
}

// ------------------------------------------------- MITM swaps in a delta CRL

/// CDP URLs are typically plain http. A network attacker answers the CDP
/// fetch with the CA's own (validly signed, fresh) delta CRL instead of the
/// complete CRL. `HttpCrlFetcher` hands it to `CrlChecker::new`, which used
/// to accept a delta as if it were complete: the revoked cert passed.
#[test]
fn review_http_crl_fetcher_rejects_delta_crl_served_at_cdp() {
    let f = Sequence::new(vec![fx("delta-crl.der")]);
    let h = HttpCrlFetcher::new(&f, DefaultVerifier, NOW);
    let r = h.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der"));
    assert!(
        r.is_err(),
        "delta CRL at CDP made a revoked cert pass; got {r:?}"
    );
}

// ---------------------------------------------------- cache poisoning (DoS)

/// The cache used to be populated BEFORE the CRL signature was verified, and
/// a cache hit returned the checker verdict without falling back to the
/// network. One forged response (bad signature, nextUpdate 2099, CRLNumber
/// 2^62) was thus pinned until 2099, and the CRLNumber rollback guard also
/// blocked the genuine CRL from ever replacing it.
#[test]
fn review_cached_crl_fetcher_does_not_cache_unverified_crl() {
    let f = Sequence::new(vec![fx("forged-crl.der"), fx("base-crl.der")]);
    let h = CachedHttpCrlFetcher::new(
        HttpCrlFetcher::new(&f, DefaultVerifier, NOW),
        InMemoryCache::new(),
    );
    let leaf = cert("leaf-serial2.der");
    let ca = cert("ca.der");

    let first = h.check_revocation(&leaf, &ca);
    assert!(
        matches!(first, Err(RevError::CrlSignatureInvalid)),
        "precondition: {first:?}"
    );

    let second = h.check_revocation(&leaf, &ca);
    assert!(
        matches!(second, Err(RevError::Revoked { .. })),
        "after a forged CRL the genuine CRL must be fetched and applied; got {second:?} \
         with {} total fetches (forged CRL served from cache)",
        f.calls()
    );
}

/// Same as above for OCSP: an unauthenticated response (signed by an
/// unrelated key, nextUpdate 2099) was cached and replayed on every check.
#[test]
fn review_cached_ocsp_fetcher_does_not_cache_unverified_response() {
    let f = Sequence::new(vec![
        fx("ocsp-forged-serial2-good.der"),
        fx("ocsp-serial2-revoked.der"),
    ]);
    let h = CachedHttpOcspFetcher::new(
        HttpOcspFetcher::new(&f, DefaultVerifier, NOW),
        InMemoryCache::new(),
    );
    let leaf = cert("leaf-serial2.der");
    let ca = cert("ca.der");

    let first = h.check_revocation(&leaf, &ca);
    assert!(
        first.is_err() && !matches!(first, Err(RevError::Revoked { .. })),
        "precondition: {first:?}"
    );

    let second = h.check_revocation(&leaf, &ca);
    assert!(
        matches!(second, Err(RevError::Revoked { .. })),
        "after a forged OCSP response the genuine one must be fetched; got {second:?} \
         with {} total fetches (forged response served from cache)",
        f.calls()
    );
}
